# Two Sum - sorted array
def two_sum(nums, target):
    left, right = 0, len(nums) - 1
    while left < right:
        current = nums[left] + nums[right]
        if current == target:
            return [left, right]
        elif current < target:
            left += 1  # Need larger sum
        else:
            right -= 1  # Need smaller sum
    return []
